SELECT AVG(CAST(metric_0001 AS DOUBLE PRECISION)) AS avg_metric_0001, AVG(CAST(metric_0223 AS DOUBLE PRECISION)) AS avg_metric_0223, AVG(CAST(metric_0445 AS DOUBLE PRECISION)) AS avg_metric_0445, AVG(CAST(metric_0667 AS DOUBLE PRECISION)) AS avg_metric_0667, AVG(CAST(metric_0889 AS DOUBLE PRECISION)) AS avg_metric_0889, AVG(CAST(metric_1111 AS DOUBLE PRECISION)) AS avg_metric_1111, AVG(CAST(metric_1333 AS DOUBLE PRECISION)) AS avg_metric_1333, AVG(CAST(metric_1555 AS DOUBLE PRECISION)) AS avg_metric_1555, AVG(CAST(metric_1777 AS DOUBLE PRECISION)) AS avg_metric_1777, AVG(CAST(metric_2000 AS DOUBLE PRECISION)) AS avg_metric_2000 FROM wide2000 PREWHERE time >= '2024-12-22' AND time < '2025-01-01'
